    move_id = fields.Many2one(comodel_name="account.move", string="Journal Entry", required=True, readonly=True)
    journal_id = fields.Many2one(comodel_name="account.journal", string="Journal", readonly=True)
    company_id = fields.Many2one(comodel_name="res.company", string="Company", readonly=True)
    company_currency_id = fields.Many2one(comodel_name="res.currency", string="Company Currency", readonly=True)
    move_name = fields.Char(string="Number", readonly=True)
    parent_state = fields.Selection(selection=[["draft","Draft"],["posted","Posted"],["cancel","Cancelled"]], string="Status", readonly=True)
    date = fields.Date(string="Date", readonly=True)
    ref = fields.Char(string="Reference", readonly=True)
    is_storno = fields.Boolean(string="Company Storno Accounting", readonly=True, help="Utility field to express whether the journal item is subject to storno accounting")
    sequence = fields.Integer(string="Sequence")
    move_type = fields.Selection(selection=[["entry","Journal Entry"],["out_invoice","Customer Invoice"],["out_refund","Customer Credit Note"],["in_invoice","Vendor Bill"],["in_refund","Vendor Credit Note"],["out_receipt","Sales Receipt"],["in_receipt","Purchase Receipt"]], string="Type", readonly=True)
    account_id = fields.Many2one(comodel_name="account.account", string="Account")
    name = fields.Char(string="Label")
    debit = fields.Monetary(string="Debit")
    credit = fields.Monetary(string="Credit")
    balance = fields.Monetary(string="Balance")
