    currency_rate = fields.Float(string="Currency Rate", readonly=True, help="Currency rate from company currency to document currency.")
    amount_currency = fields.Monetary(string="Amount in Currency", help="The amount expressed in an optional other currency if it is a multi-currency entry.")
    currency_id = fields.Many2one(comodel_name="res.currency", string="Currency", required=True)
    is_same_currency = fields.Boolean(string="Is Same Currency", readonly=True)
