    tax_ids = fields.Many2many(comodel_name="account.tax", string="Taxes")
    group_tax_id = fields.Many2one(comodel_name="account.tax", string="Originator Group of Taxes")
    tax_line_id = fields.Many2one(comodel_name="account.tax", string="Originator Tax", readonly=True, help="Indicates that this journal item is a tax line")
    tax_group_id = fields.Many2one(comodel_name="account.tax.group", string="Originator tax group", readonly=True)
    tax_base_amount = fields.Monetary(string="Base Amount", readonly=True)
