    account_internal_group = fields.Selection(selection=[["equity","Equity"],["asset","Asset"],["liability","Liability"],["income","Income"],["expense","Expense"],["off_balance","Off Balance"]], string="Internal Group", readonly=True)
    account_root_id = fields.Many2one(comodel_name="account.root", string="Account Root", readonly=True)
    display_type = fields.Selection(selection=[["product","Product"],["cogs","Cost of Goods Sold"],["tax","Tax"],["rounding","Rounding"],["payment_term","Payment Term"],["line_section","Section"],["line_note","Note"],["epd","Early Payment Discount"]], string="Display Type", required=True)
    product_id = fields.Many2one(comodel_name="product.product", string="Product")
    product_uom_id = fields.Many2one(comodel_name="uom.uom", string="Unit of Measure")
