    forward_rule_id = fields.Many2one(comodel_name="balance.carry.forward.rule", string="Balance Carry Forward Rule", readonly=True, help="The Balance Carry Forward Rule that created this journal item")
    reversed_move_line_ids = fields.One2many(comodel_name="account.move.line", inverse_name='parent_id', string="Journal Items", readonly=True)
    reversed_move_line_id = fields.Many2one(comodel_name="account.move.line", string="Reversal of")
    transfer_line_id = fields.Many2one(comodel_name="account.move.line", string="Transfer To", readonly=True, help="The technical field that stores the journal item which holds the amount transfer to")
