    transferred_amount = fields.Monetary(string="Transferred Amount", readonly=True)
    transferred_amount_currency = fields.Monetary(string="Transferred Amount Currency", readonly=True)
    transferred_percentage = fields.Float(string="Transferred Percentage", readonly=True)
    to_transfer_amount = fields.Monetary(string="To Transfer Amount", readonly=True)
    to_transfer_amount_currency = fields.Monetary(string="To Transfer Amount Currency", readonly=True)
    to_transfer_percentage = fields.Float(string="To Transfer Percentage", readonly=True)
    transferred_to_line_ids = fields.Many2many(comodel_name="account.move.line", string="Transferred To", readonly=True, help="The technical field that stores the journal items to which the current item was transferred to")
    transfer_from_allocation_ids = fields.One2many(comodel_name="account.transfer.allocation", inverse_name='parent_id', string="Transfer From Allocations", readonly=True)
    transferred_from_line_ids = fields.Many2many(comodel_name="account.move.line", string="Transferred From", help="The technical field that stores all the journal items whose amount is transfered from")
    analytic_tag_ids = fields.Many2many(comodel_name="account.analytic.tag", string="Analytic Tags")
    cr_ctp_ids = fields.One2many(comodel_name="account.move.line.ctp", inverse_name='parent_id', string="Credit Counterparts", help="Technical field to link credit counterparts with this journal item")
    dr_ctp_ids = fields.One2many(comodel_name="account.move.line.ctp", inverse_name='parent_id', string="Debit Counterparts", help="Technical field to link debit counterparts with this journal item")
    ctp_ids = fields.Many2many(comodel_name="account.move.line.ctp", string="Counterparts", readonly=True)
    ctp_aml_ids = fields.Many2many(comodel_name="account.move.line", string="Countered Journal Items", readonly=True, help="The Journal Items that are countered with this Journal Item")
    ctp_account_ids = fields.Many2many(comodel_name="account.account", string="Countered Accounts", readonly=True, help="The Accounts that are countered with the account of this Journal Item")
    countered_amt = fields.Monetary(string="Countered Amount", readonly=True, help="The amount that has been countered for this journal item")
    countered_amt_currency = fields.Monetary(string="Countered Amount Currency", readonly=True, help="The amount in the original currency that has been countered for this journal item")
    countered_status = fields.Selection(selection=[["none","Not Countered"],["partially","Partially Countered"],["fully","Fully Countered"]], string="Countered Status", readonly=True, help="A technical field to indicate that this journal item has either countered fully or partially or not-yet-countered")
    asset_category_id = fields.Many2one(comodel_name="account.asset.category", string="Asset Category", help="If set, it will automatically generate the corresponding assets.")
    asset_start_date = fields.Date(string="Asset Start Date", readonly=True)
    asset_end_date = fields.Date(string="Asset End Date", readonly=True)
    asset_mrr = fields.Float(string="Monthly Recurring Revenue", readonly=True)
    payable_account_id = fields.Many2one(comodel_name="account.account", string="Payable Account", help="Tài khoản phải trả riêng cho dòng phí này. Nếu điền, bút toán phải trả sẽ tách riêng theo tài khoản này.")
    freight_debit_line_ids = fields.Many2many(comodel_name="freight.debit.note.line", string="Debit Note Lines", readonly=True)
    freight_dc_line_ids = fields.Many2many(comodel_name="freight.dc.note.line", string="DC Note Lines", readonly=True)
    freight_credit_line_ids = fields.Many2many(comodel_name="freight.credit.note.line", string="Credit Note Lines", readonly=True)
    foreign_currency_id = fields.Many2one(comodel_name="res.currency", string="Foreign Currency", readonly=True, help="Nguyên tệ gốc của dòng debit/dc note khi hóa đơn được ép về VND.")
    foreign_amount_untaxed = fields.Monetary(string="Foreign Amount (Untaxed)", readonly=True, help="Số tiền chưa thuế theo nguyên tệ gốc của dòng debit/dc note.")
    foreign_amount_total = fields.Monetary(string="Foreign Amount (Total)", readonly=True, help="Số tiền gồm thuế theo nguyên tệ gốc của dòng debit/dc note.")
    plate_number = fields.Char(string="Plate Number")
    ar_lot_ref = fields.Char(string="AR Lot Ref", help="Shipment number (House B/L / Job) of an opening balance line, used by the AR Invoice Detail report to group the line into that shipment.")
